async function(handle, args) {
const limit = args.limit || 50;
return await handle.eval((limitArg) => {
      const out = [];
      const rows = document.querySelectorAll("table tbody tr, #pl_top_realtimehot table tbody tr");
      for (const tr of rows) {
        if (out.length >= limitArg) break;
        const cells = tr.querySelectorAll("td");
        if (cells.length < 2) continue;
        // Column layout: [rank, title+tags, hot-value]
        const rankEl = cells[0];
        const titleCell = cells[1];
        const hotCell = cells[2];
        const link = titleCell.querySelector("a");
        const title = (link?.textContent || titleCell.textContent || "").trim();
        const href = link?.getAttribute("href") || "";
        const url = href ? (href.startsWith("http") ? href : "https://s.weibo.com" + href) : "";
        const rankText = (rankEl?.textContent || "").trim();
        // Skip the sticky "置顶" / ad row if no rank number
        if (!title) continue;
        // Tag (新/热/沸/荐 etc.) usually in a span inside titleCell
        const tagEl = titleCell.querySelector("span, i");
        const tag = (tagEl?.textContent || "").trim();
        const hot = ((hotCell?.textContent) || "").trim();
        out.push({
          rank: rankText || String(out.length + 1),
          title,
          tag,
          hot,
          url,
        });
      }
      return out;
    }, limit);
}
